-- Series batch test: stage Death Note (VIZ Media, English) volumes 6-12 for
-- staff review, so the series can be completed in one review session instead
-- of one volume a day.
--
-- RAR already has volumes 1-4 (VIZ, ISBN 9781421501680, 9781421501697,
-- 9781421501703, 9781421503318). Volume 5 (9781421506265) is already in the
-- review queue from the daily intake and is not duplicated here. The VIZ
-- English paperback run is 12 volumes.
--
-- Each row carries the exact ISBN-13 and two human-readable retailer pages
-- showing that ISBN with the volume title (found by web search on 18 Nov
-- 2026). Nothing enters the catalogue until a person approves it on the
-- Catalogue review page; release dates and covers are left empty rather
-- than guessed.
--
-- Additive only. To undo before review:
--   delete from catalogue_import_queue
--   where raw_payload ? 'series_batch' and status = 'pending_review'
--     and candidate_series = 'Death Note';

begin;

insert into public.sources (name, base_url, source_type, trust_tier, notes)
values ('Book retailer listing', null, 'catalog', 3,
  'A bookseller or library page showing the exact ISBN-13 and title. Reference for staff review, not proof of a cover or printing.')
on conflict (name) do nothing;

insert into public.catalogue_import_queue
  (source_id, external_id, source_record_url, raw_payload, candidate_kind, candidate_title,
   candidate_series, candidate_volume_number, candidate_author, candidate_publisher,
   candidate_language, candidate_isbn_13, candidate_format)
select v.* from (values
  ((select id from public.sources where name = 'Book retailer listing'), 'isbn:9781421506272', 'https://www.thenile.co.nz/books/tsugumi-ohba/death-note-vol-6-give-and-take-death-note-book-6/9781421506272', '{"series_batch": {"series": "Death Note", "edition_line": "VIZ Media English paperback (Shonen Jump Advanced), 12 volumes", "volume": 6, "isbn_13": "9781421506272", "reference_urls": ["https://www.thenile.co.nz/books/tsugumi-ohba/death-note-vol-6-give-and-take-death-note-book-6/9781421506272", "https://www.booksamillion.com/p/9781421506272"], "existing_rar_volumes": "1-4 (ISBN 9781421501680, 9781421501697, 9781421501703, 9781421503318)", "note": "Staged by the series batch test on 18 Nov 2026. ISBN and title from retailer listings found by web search; the pages were not opened here. Confirm the cover and ISBN before approving. Volume 5 was already pending from the daily intake (Open Library) and is not duplicated."}}'::jsonb, 'edition_candidate', 'Death Note, Vol. 6: Give-and-Take', 'Death Note', '6', 'Tsugumi Ohba; Takeshi Obata', 'VIZ Media', 'English', '9781421506272', 'Paperback'),
  ((select id from public.sources where name = 'Book retailer listing'), 'isbn:9781421506289', 'https://www.abebooks.co.uk/9781421506289/Death-Note-Volume-7-Ohba-1421506289/plp', '{"series_batch": {"series": "Death Note", "edition_line": "VIZ Media English paperback (Shonen Jump Advanced), 12 volumes", "volume": 7, "isbn_13": "9781421506289", "reference_urls": ["https://www.abebooks.co.uk/9781421506289/Death-Note-Volume-7-Ohba-1421506289/plp", "https://simonandschuster.co.in/books/Death-Note-Vol-7/Tsugumi-Ohba/9781421506289"], "existing_rar_volumes": "1-4 (ISBN 9781421501680, 9781421501697, 9781421501703, 9781421503318)", "note": "Staged by the series batch test on 18 Nov 2026. ISBN and title from retailer listings found by web search; the pages were not opened here. Confirm the cover and ISBN before approving. Volume 5 was already pending from the daily intake (Open Library) and is not duplicated."}}'::jsonb, 'edition_candidate', 'Death Note, Vol. 7: Zero', 'Death Note', '7', 'Tsugumi Ohba; Takeshi Obata', 'VIZ Media', 'English', '9781421506289', 'Paperback'),
  ((select id from public.sources where name = 'Book retailer listing'), 'isbn:9781421506296', 'https://www.thenile.co.nz/books/tsugumi-ohba/death-note-vol-8-target-death-note-book-8/9781421506296', '{"series_batch": {"series": "Death Note", "edition_line": "VIZ Media English paperback (Shonen Jump Advanced), 12 volumes", "volume": 8, "isbn_13": "9781421506296", "reference_urls": ["https://www.thenile.co.nz/books/tsugumi-ohba/death-note-vol-8-target-death-note-book-8/9781421506296", "https://openlibrary.org/books/OL8490847M/Death_Note_Volume_8"], "existing_rar_volumes": "1-4 (ISBN 9781421501680, 9781421501697, 9781421501703, 9781421503318)", "note": "Staged by the series batch test on 18 Nov 2026. ISBN and title from retailer listings found by web search; the pages were not opened here. Confirm the cover and ISBN before approving. Volume 5 was already pending from the daily intake (Open Library) and is not duplicated."}}'::jsonb, 'edition_candidate', 'Death Note, Vol. 8: Target', 'Death Note', '8', 'Tsugumi Ohba; Takeshi Obata', 'VIZ Media', 'English', '9781421506296', 'Paperback'),
  ((select id from public.sources where name = 'Book retailer listing'), 'isbn:9781421506302', 'https://www.booksamillion.com/p/9781421506302', '{"series_batch": {"series": "Death Note", "edition_line": "VIZ Media English paperback (Shonen Jump Advanced), 12 volumes", "volume": 9, "isbn_13": "9781421506302", "reference_urls": ["https://www.booksamillion.com/p/9781421506302", "https://openlibrary.org/books/OL8490848M/Death_Note_Volume_9"], "existing_rar_volumes": "1-4 (ISBN 9781421501680, 9781421501697, 9781421501703, 9781421503318)", "note": "Staged by the series batch test on 18 Nov 2026. ISBN and title from retailer listings found by web search; the pages were not opened here. Confirm the cover and ISBN before approving. Volume 5 was already pending from the daily intake (Open Library) and is not duplicated."}}'::jsonb, 'edition_candidate', 'Death Note, Vol. 9: Contact', 'Death Note', '9', 'Tsugumi Ohba; Takeshi Obata', 'VIZ Media', 'English', '9781421506302', 'Paperback'),
  ((select id from public.sources where name = 'Book retailer listing'), 'isbn:9781421511559', 'https://www.harryhartog.com.au/products/death-note-vol-10-volume-10-tsugumi-ohba-9781421511559', '{"series_batch": {"series": "Death Note", "edition_line": "VIZ Media English paperback (Shonen Jump Advanced), 12 volumes", "volume": 10, "isbn_13": "9781421511559", "reference_urls": ["https://www.harryhartog.com.au/products/death-note-vol-10-volume-10-tsugumi-ohba-9781421511559", "https://www.booksamillion.com/p/9781421511559"], "existing_rar_volumes": "1-4 (ISBN 9781421501680, 9781421501697, 9781421501703, 9781421503318)", "note": "Staged by the series batch test on 18 Nov 2026. ISBN and title from retailer listings found by web search; the pages were not opened here. Confirm the cover and ISBN before approving. Volume 5 was already pending from the daily intake (Open Library) and is not duplicated."}}'::jsonb, 'edition_candidate', 'Death Note, Vol. 10: Deletion', 'Death Note', '10', 'Tsugumi Ohba; Takeshi Obata', 'VIZ Media', 'English', '9781421511559', 'Paperback'),
  ((select id from public.sources where name = 'Book retailer listing'), 'isbn:9781421511788', 'https://www.thenile.co.nz/books/tsugumi-ohba/death-note-vol-11-kindred-spirit-death-note-book-11/9781421511788', '{"series_batch": {"series": "Death Note", "edition_line": "VIZ Media English paperback (Shonen Jump Advanced), 12 volumes", "volume": 11, "isbn_13": "9781421511788", "reference_urls": ["https://www.thenile.co.nz/books/tsugumi-ohba/death-note-vol-11-kindred-spirit-death-note-book-11/9781421511788", "https://www.simonandschuster.co.uk/books/Death-Note-Vol-11/Tsugumi-Ohba/Death-Note/9781421511788"], "existing_rar_volumes": "1-4 (ISBN 9781421501680, 9781421501697, 9781421501703, 9781421503318)", "note": "Staged by the series batch test on 18 Nov 2026. ISBN and title from retailer listings found by web search; the pages were not opened here. Confirm the cover and ISBN before approving. Volume 5 was already pending from the daily intake (Open Library) and is not duplicated."}}'::jsonb, 'edition_candidate', 'Death Note, Vol. 11: Kindred Spirit', 'Death Note', '11', 'Tsugumi Ohba; Takeshi Obata', 'VIZ Media', 'English', '9781421511788', 'Paperback'),
  ((select id from public.sources where name = 'Book retailer listing'), 'isbn:9781421513270', 'https://www.thenile.co.nz/books/tsugumi-ohba/death-note-vol-12-finis-death-note-book-12/9781421513270', '{"series_batch": {"series": "Death Note", "edition_line": "VIZ Media English paperback (Shonen Jump Advanced), 12 volumes", "volume": 12, "isbn_13": "9781421513270", "reference_urls": ["https://www.thenile.co.nz/books/tsugumi-ohba/death-note-vol-12-finis-death-note-book-12/9781421513270", "https://www.simonandschuster.co.uk/books/Death-Note-Vol-12/Tsugumi-Ohba/9781421513270"], "existing_rar_volumes": "1-4 (ISBN 9781421501680, 9781421501697, 9781421501703, 9781421503318)", "note": "Staged by the series batch test on 18 Nov 2026. ISBN and title from retailer listings found by web search; the pages were not opened here. Confirm the cover and ISBN before approving. Volume 5 was already pending from the daily intake (Open Library) and is not duplicated."}}'::jsonb, 'edition_candidate', 'Death Note, Vol. 12: Finis', 'Death Note', '12', 'Tsugumi Ohba; Takeshi Obata', 'VIZ Media', 'English', '9781421513270', 'Paperback')
) as v(source_id, external_id, source_record_url, raw_payload, candidate_kind, candidate_title,
       candidate_series, candidate_volume_number, candidate_author, candidate_publisher,
       candidate_language, candidate_isbn_13, candidate_format)
where not exists (select 1 from public.manga_editions e where e.isbn_13 = v.candidate_isbn_13)
  and not exists (select 1 from public.catalogue_import_queue q where q.candidate_isbn_13 = v.candidate_isbn_13)
on conflict (source_id, external_id) do nothing;

commit;
